    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_count += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 28.0))
        return float(min(budget, 8.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    total_players = 1 + len(alive)
    expected_winners = max(1, int(supply // WATER_REQ))
    scarcity = total_players - expected_winners

    must_win = False
    if hp <= 2:
        must_win = True
    if no_water_days >= 1 and hp <= 4:
        must_win = True
    if no_water_days >= 2:
        must_win = True

    if must_win:
        bid = max(63.0, max_prev + 2.5)
        if rich_count >= 2:
            bid = max(bid, 92.0)
        if scarcity >= 2:
            bid = max(bid, 105.0)
        return float(min(budget, bid))

    if expected_winners >= total_players - 1:
        if no_water_days == 0 and hp >= 5:
            return float(min(budget, 12.0))
        return float(min(budget, 24.0))

    if scarcity >= 3:
        if hp >= 6 and no_water_days == 0:
            return float(min(budget, 18.0))
        bid = max(48.0, avg_prev * 0.55)
        return float(min(budget, bid))

    if max_prev >= 160:
        if hp >= 5 and no_water_days == 0:
            return float(min(budget, 20.0))
        return float(min(budget, 72.0))

    if max_prev >= 110:
        if hp >= 6 and no_water_days == 0 and supply >= 20:
            return float(min(budget, 22.0))
        bid = max(58.0, min(86.0, max_prev * 0.62))
        return float(min(budget, bid))

    if desperate_count >= 2:
        bid = max(52.0, max_prev + 1.5)
        return float(min(budget, bid))

    base = 36.0
    if supply <= 16:
        base += 10.0
    if hp <= 4:
        base += 8.0
    if no_water_days >= 1:
        base += 12.0
    bid = max(base, avg_prev * 0.7)
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((agent_id, opp))

    if not alive_opponents:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace only (immediate reaction)
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = sorted(yesterday_bids, reverse=True)[1] if len(yesterday_bids) >= 2 else 0.0

    # Supply pressure: if supply is close to our requirement, water is scarce => bid more.
    # If supply is comfortably above requirement, we can bid lower.
    scarcity_ratio = supply / float(WATER_REQ) if WATER_REQ > 0 else 1.0
    if scarcity_ratio <= 1.2:
        scarcity_factor = 1.15
    elif scarcity_ratio <= 1.6:
        scarcity_factor = 1.0
    else:
        scarcity_factor = 0.85

    # If we are at/near critical hp, prioritize survival.
    critical = (my_hp <= 2) or (my_no_water_days >= 2)

    # Decide based on opponent yesterday intensity.
    # If someone previously bid very high (near salary), assume aggressive contest today.
    aggressive_threshold = DAILY_SALARY * 0.85

    # Base bid target
    if highest_prev_bid >= aggressive_threshold:
        # Try to beat the likely top bidder without going all-in.
        target = highest_prev_bid + 2.0
        if critical:
            target = max(target, DAILY_SALARY * 0.95)
        else:
            target = min(target, DAILY_SALARY * 0.75)
    else:
        # If no extreme aggression, bid around the second-highest to secure water.
        # Use highest_prev_bid as a soft anchor.
        anchor = max(second_prev_bid, highest_prev_bid * 0.8)
        target = max(DAILY_SALARY * 0.45, anchor + 1.5)
        if critical:
            target = max(target, DAILY_SALARY * 0.85)

    target *= scarcity_factor

    # Final caps to respect budget and avoid unnecessary overpaying.
    # If budget is low, spend what we can but still follow critical logic.
    max_reasonable = DAILY_SALARY * 1.05
    bid = min(my_budget, min(target, max_reasonable))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQUIREMENT = 13
    MY_DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], MY_DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = MY_DAILY_SALARY * 0.8

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        target_bid = highest_prev_bid + 5.0 
        target_bid = max(target_bid, base_bid)
    else:
        target_bid = base_bid

    if my_status['hp'] <= 2: 
        target_bid = max(target_bid, MY_DAILY_SALARY * 1.3) 
        if yesterday_bids:
            target_bid = max(target_bid, max(yesterday_bids) + 15.0)
    elif my_status['hp'] <= 4: 
        target_bid = max(target_bid, MY_DAILY_SALARY * 1.05) 
        if yesterday_bids:
            target_bid = max(target_bid, max(yesterday_bids) + 10.0)
    elif my_status['hp'] <= 6: 
        target_bid = max(target_bid, MY_DAILY_SALARY * 0.9) 

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2: 
        target_bid = max(target_bid, MY_DAILY_SALARY * 1.2) 
        if yesterday_bids:
            target_bid = max(target_bid, max(yesterday_bids) + 12.0)
    elif remaining_days <= 4: 
        target_bid = max(target_bid, MY_DAILY_SALARY * 1.0) 

    final_bid = min(my_status['budget'], target_bid)
    final_bid = max(0.0, final_bid)

    return final_bid
